};
scwin.fn_SetCode = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.select.stock_satisfy.stdyear";
    dts_STD_YEAR_1.DataID = encodeURI(url);
    dts_STD_YEAR_1.reset();
    $c.stf.CopyDataSet(dts_STD_YEAR_1, dts_STD_YEAR_2);
    cmb_STD_YEAR_2.setSelectedIndex(0);
    cmb_STD_YEAR_3.setSelectedIndex(0);
    dts_DepCd.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=DR&outputMessageId=AADD_OUT_COMBO";
    dts_DepCd.Reset();
    dts_EmpNo.DataID = "/AdminAndDlstedDetection.do?method=getComboList&For=ER&outputMessageId=AADD_OUT_COMBO";
    dts_EmpNo.Reset();
};


/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 목록조회
 ***********************************************/
scwin.fn_list_sync_sum = function() {
    var f_mm = $c.cp.valueOfIndex(cmb_f_mm_1, "CODE", cmb_f_mm_1.getSelectedIndex());
    var base_dt = $c.stf.getObjectValue(cmb_STD_YEAR_1);
    var team_cd = $c.cp.valueOfIndex(cmb_dep_cd_1, "VALUE", cmb_dep_cd_1.getSelectedIndex());
    var charge_id = $c.cp.valueOfIndex(cmb_emp_no_1, "VALUE", cmb_emp_no_1.getSelectedIndex());
    var gubun_id = $c.cp.valueOfIndex(cmb_gubun, "CODE", cmb_gubun.getSelectedIndex());
    var dsNm = 'AADD_OUT_SSF_SUM';
    var qryId = 'krx.lds.stf.lstmgt.detection.stock_satisfy.list.sumcnt';
    var param = '&{P}V_F_MM=' + f_mm;
    param += '&{P}V_BASE_DT=' + base_dt;
    param += '&{P}V_TEAM_CD=' + team_cd;
    param += '&{P}V_CHARGE_ID=' + charge_id;
    param += '&{P}V_SATISFACT_TYP=' + gubun_id;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts1_Sum, dsNm, qryId, param);
};



