scwin.cmb_dep_cd_1_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_dep_cd_1, "VALUE", cmb_dep_cd_1.getSelectedIndex());
    dts_EmpNo.UseFilter = true;
    dts_EmpNo.Filter();
    cmb_emp_no_1.ComboDataID = "dts_EmpNo";
};
scwin.cmb_dep_cd_2_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_dep_cd_2, "VALUE", cmb_dep_cd_2.getSelectedIndex());
    dts_EmpNo.UseFilter = true;
    dts_EmpNo.Filter();
    cmb_emp_no_2.ComboDataID = "dts_EmpNo";
};
