    scwin.gDepCd = $c.cp.valueOfIndex(cmb_dep_cd_3, "VALUE", cmb_dep_cd_3.getSelectedIndex());
    dts_EmpNo.UseFilter = true;
    dts_EmpNo.Filter();
    cmb_emp_no_3.ComboDataID = "dts_EmpNo";
};
scwin.dts_EmpNo_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "%") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        //alert(dts_EmpNo.NameValue(row, "DEP_CD") );
        if (dts_EmpNo.getCellData(row, "DEP_CD") == scwin.gDepCd ||
            dts_EmpNo.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    var eCnt = 0; // 각 dataset 별 표시 count
    var tIndex = MxTab_1.getSelectedTabIndex();
    //alert(tIndex);
    if (tIndex == 1) {
        eCnt = dts1.getTotalRow();
    } else if (tIndex == 2) {
        eCnt = dts2.getTotalRow();
    } else if (tIndex == 3) {
        eCnt = dts3.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(eCnt, panel_page);

    //tab을 선택 시 기존 그리드의 '조회결과 없음'표시를 닫는다.
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Excel_onclick = function() {
    var tIndex = MxTab_1.getSelectedTabIndex();
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    //alert(tIndex);
    if (tIndex == 1) {
        $c.data.downloadGridViewExcel(grd_satisfy, "주식분산-충족여부 목록", "", "8");
    } else if (tIndex == 2) {
        $c.data.downloadGridViewExcel(grd_corp_dtl, "주식분산-법인별 현황 목록", "", "8");
    } else if (tIndex == 3) {
        $c.data.downloadGridViewExcel(grd_kn_satisfy, "주식분산-종류주식", "", "8");
    }
};
