    MxTab_1.setSelectedTabIndex(1);
    scwin.fn_SetCode();
    //dts1_Sum.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 


    //fn_com_isur(txb_ISU_CD, txb_COM_NM);
    //Grd_com_isur.style.zIndex = 30;

    //round처리
    $c.cm.PanelToGroupBox(panel_2);
    $c.libRoundPanel.PanelToGroupBox(panel_4);
};
